'use strict';
// «Контрастный режим» in the village (UI_RULES §16): the path edges layer village-contrast-paths.svg (generated by
// scripts/art/village/contrast_paths.js; reproducibility in scripts/art/village/test_reproducible.py) is hidden without the
// mode and shown with html[data-qw-contrast="1"], day and night, fetched only once the mode is on.
const test=require('node:test'),assert=require('node:assert/strict'),fs=require('fs'),path=require('path');
const stat=path.join(__dirname,'../../qw_farm/static');
const app=fs.readFileSync(path.join(stat,'app.js'),'utf8'),css=fs.readFileSync(path.join(stat,'style.css'),'utf8');
const api=fs.readFileSync(path.join(__dirname,'../../qw_farm/api.py'),'utf8');
const svg=fs.readFileSync(path.join(stat,'village-contrast-paths.svg'),'utf8');

// the CSS rules that decide whether .village-contrast is displayed, evaluated for a given <html>
const rules=[...css.replace(/\/\*[\s\S]*?\*\//g,'').matchAll(/([^{}]*\.village-contrast[^{}]*)\{([^}]*)\}/g)].map(m=>[m[1].trim(),m[2]]);
function shown(html){
 let display='block';
 for(const [sel,body] of rules){
  const d=/display:([a-z]+)/.exec(body);if(!d)continue;
  for(const one of sel.split(',').map(x=>x.trim())){
   if(!/\.village-contrast$/.test(one))continue;
   const need=[...one.matchAll(/\[([a-z-]+)(?:="?([^"\]]*)"?)?\]/g)];
   const neg=/:not\(/.test(one);
   if(neg)continue;
   if(need.every(([,k,v])=>v===undefined?k in html:html[k]===v))display=d[1];
  }
 }
 return display!=='none';
}

test('contrast paths layer: vector only, CSP-safe, one stroke colour over the 2400x1800 world',()=>{
 assert.match(svg,/^<svg [^>]*viewBox="0 0 2400 1800"/);
 assert.doesNotMatch(svg,/<image|data:|<style|style=|<script|href=/i);
 assert.match(svg,/stroke="#3a2610"/);
 assert.ok(svg.length<60000,'stays light');
});
test('hidden without the mode, shown with html[data-qw-contrast="1"] by day and at night',()=>{
 assert.equal(shown({}),false);
 assert.equal(shown({'data-farm-theme':'night'}),false);
 assert.equal(shown({'data-qw-contrast':'1'}),true);
 assert.equal(shown({'data-qw-contrast':'1','data-farm-theme':'night'}),true);
 assert.equal(shown({'data-qw-contrast':'0'}),false);
});
test('served as an asset, fetched only in the mode, placed under the night tint and refreshed on qw:contrast',()=>{
 assert.match(api,/'village-contrast-paths\.svg'/);
 assert.match(app,/const VILLAGE_CONTRAST='village-contrast-paths\.svg'/);
 assert.match(app,/getAttribute\?\.\('data-qw-contrast'\)==='1'[^;]*;\n if\(!on\|\|!layer\|\|layer\.firstChild\)return;/,'nothing is fetched while the mode is off');
 assert.match(app,/villageFestLayer\('base'\),villageContrastLayer\(\),villageBuildLayer\('base'\),sun,villageFx\(\),night,/,'under the night tint');
 assert.match(app,/addEventListener\?\.\('qw:contrast',\(\)=>syncVillageContrast\(\)\)/);
 assert.match(app,/syncVillageBuild\(\);syncVillageContrast\(\);/);
});
